#!/usr/bin/env python3
"""সহযোগী বৌদ্ধ ঐতিহাসিক সংরক্ষণাগার — ডেটা-বিল্ডার।

চারটি প্রতিষ্ঠানের প্রকাশ্য সংগ্রহ থেকে হাতে-যাচাই করা (২০২৬-১১-০১) রেকর্ড
এখানে একটি JSON রেজিস্ট্রিতে লেখা হয়:

  1. BDRC / BUDA — Buddhist Digital Archives      (library.bdrc.io)
  2. Buddhist Archive of Photography, Luang Prabang (buddhist-archive.org)
  3. 불교기록문화유산 아카이브 KABC, Dongguk Univ.    (kabc.dongguk.edu)
  4. Rare Buddhist Texts Archive, Univ. of Arizona (cbs.arizona.edu)

নীতি: পূর্ণ-রেজুলেশনের ছবি/অডিও কখনো এখানে কপি করা হয় না — প্রতিটি রেকর্ডে
প্রতিষ্ঠানের নিজস্ব পাতার লিংক, সংগ্রহ-নম্বর, তারিখ ও অধিকার-লেবেল থাকে।
Buddhist Archive of Photography পুনঃপ্রকাশ নিষিদ্ধ করেছে, তাই সেখানে কোনো
ছবি নেই (কেবল লিংক)। KABC ও Arizona নিজেরাই যে ছোট থাম্বনেইল প্রকাশ্যে দেখায়,
সেগুলো `assets/archive/partners/`-এ ছোট কপি হিসেবে রাখা হয় যাতে নেটওয়ার্ক
ছাড়াও কার্ড দেখা যায়; প্রতিটি রেকর্ডে মূল URL (`imageSourceUrl`) ও স্বীকৃতি
(`imageCreditBn`) সংরক্ষিত থাকে — কেবল প্রদর্শনের ব্যবহার, সব অধিকার মূল প্রতিষ্ঠানের।

Run:  python tools/build_partner_archive.py            # ডেটা লেখে
      python tools/build_partner_archive.py --fetch    # থাম্বনেইলও নামায় (ঐচ্ছিক)
"""
from __future__ import annotations

import json
import ssl
import subprocess
import sys
import urllib.request
from datetime import date
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "data" / "historical-archive-partners.json"

KABC = "https://kabc.dongguk.edu"
BOP = "https://www.buddhist-archive.org"
CBS = "https://cbs.arizona.edu/projects/rare-buddhist-texts-archive"
BDRC = "https://www.bdrc.io/buda-archive/"


THUMB_DIR = "assets/archive/partners"


def local_thumb(item_id: str, ext: str = ".jpg") -> str:
    """সাইটের ভেতরের ছোট থাম্বনেইল-পথ (assets/archive/partners/)।"""
    return f"{THUMB_DIR}/{item_id.replace('ph-', '')}{ext}"


def kabc_thumb(data_id: str) -> str:
    """KABC-র মূল থাম্বনেইল URL — JSON-এ imageSourceUrl হিসেবে থাকে।"""
    return f"{KABC}/data/image_pic/thum/{data_id}.jpg"


def kabc_pic(data_id: str) -> str:
    return f"{KABC}/content/pop_view_bulpic?dataId={data_id}"


def kabc_viewer(item_id: str, data_id: str) -> str:
    return f"{KABC}/viewer/view?itemId={item_id}&dataId={data_id}"


