def add(**kw) -> None:
    """একটি রেকর্ড যোগ করে; রিমোট থাম্বনেইল থাকলে সেটিকে স্থানীয় ছোট কপিতে বদলায়।"""
    kw.setdefault("keywords", [])
    kw.setdefault("imageUrl", "")
    kw.setdefault("imageAltBn", "")
    remote = clean_url(kw.get("imageUrl") or "")
    if remote:
        kw["imageSourceUrl"] = remote
        kw["imageUrl"] = local_thumb(kw["id"])
        kw["imageCreditBn"] = kw.get("imageCreditBn") or (
            "থাম্বনেইল: " + CREDIT.get(kw["collection"], kw["sourceUrl"])
            + " — কেবল প্রদর্শনের জন্য ছোট কপি; পূর্ণ-রেজুলেশন ও সব অধিকার মূল প্রতিষ্ঠানের।"
        )
    ITEMS.append(kw)


def clean_url(url: str) -> str:
    return url.strip() if url and url.strip().startswith("http") else ""


