    imageCreditBn="থাম্বনেইল: চলচ্চিত্রেরই একটি দৃশ্য (The Buddhist Archive of Photography / YouTube) — কেবল প্রদর্শনের জন্য ছোট কপি রাখা হয়েছে; চলচ্চিত্রটি YouTube-এ এমবেড করা, সব অধিকার নির্মাতার।",
