    descBn="২০০৬ সালে শুরু হয়ে আর্কাইভ আজ ১৯টি ভিন্ন মঠ-সংগ্রহ একত্র করেছে — ছবির পাশাপাশি তালপাতার পাণ্ডুলিপি, চিঠি, ডায়েরি ও অন্যান্য ‘ধূসর সাহিত্য’ (grey literature)। জার্মানির হামবুর্গ বিশ্ববিদ্যালয়ের এশিয়া-আফ্রিকা ইনস্টিটিউট, লাও জাতীয় গ্রন্থাগার ও ‘লাও পাণ্ডুলিপি সংরক্ষণ’ প্রকল্পের সঙ্গে যৌথ গবেষণা চলছে; শিক্ষক-প্রশিক্ষণ ও ৮০+ মঠে দেওয়া ক্যালেন্ডার এই সংগ্রহকে জীবন্ত রাখছে।",
