for p in kabc_paintings:
    _nc = KABC_NC_IMAGES.get(p["did"])
    add(
        id=f"ph-kabc-painting-{p['did'].lower().replace('_', '-')}",
        collection="kabc",
        mediaType="painting",
        period=p["period"],
        titleBn=p["titleBn"],
        titleEn=p["title"],
        origTitle=p["title"],
        dateBn=p["dateBn"],
        placeBn=f"{p['region']} · {p['temple']}" if p["temple"] != "[অজ্ঞাত]" else p["region"],
        creatorBn="অজ্ঞাত কাঠ-খোদাইকার ও মুদ্রক (মঠ-প্রেস)",
        descBn=p["descBn"],
        descEn=f"Woodblock illustration ({p['title']}) dated {p['dateBn']} from {p['region']} {p['temple']}, digitised in KABC's 변상도 collection.",
        sourceUrl=kabc_viewer("ABC_SP", p["did"]),
        imageUrl=_nc[1] if _nc else "",
        imageAltBn=f"KABC 변상도 {p['did']} — {p['titleBn']} (কাঠ-ছাপ চিত্র)",
        accession=f"KABC {p['did']}",
        materialBn="কাগজে কাঠ-খোদাই ছাপ (woodblock print)",
        language="চীনা ধ্রুপদি · কোরীয়",
        rights=KABC_RIGHTS,
        verification="primary",
        keywords=["변상도", "কাঠ-ছাপ", "চিত্রকলা", p["temple"]],
    )

