add(
    id="ph-cbs-rinzai-roku-notes",
    collection="cbs",
    mediaType="manuscript",
    period="1950-2000",
    titleBn="《লিনজি লুকু》 অনুবাদ-নোট — ১৫টি খাতা (১৯৫০-এর দশকের প্রকল্প)",
    titleEn="Translation notes of The Record of Linji (Rinzai Roku) — fifteen binders",
    origTitle="臨済録 / The Record of Linji — translation notes",
    dateBn="মূল কাজ ১৯৫০-এর দশক; ২০১৭-তে অ্যারিজোনায় অধিগ্রহণ",
    dateEn="Work of the 1950s; acquired by the Center in summer 2017",
    placeBn="যুক্তরাষ্ট্র (প্রকল্প); চীন-জাপান উৎস",
    creatorBn="রুথ ফুলার সাসাকি, ফিলিপ ইয়াম্পোলস্কি, বার্টন ওয়াটসন, গ্যারি স্নাইডার, ইরিয়া ইওশিতাকা, য়ানাগিদা সেইজান",
    descBn="চ্যান (জেন) ধারার মূল গ্রন্থ 《臨済録》-এর ইংরেজি অনুবাদে একসঙ্গে কাজ করেছিলেন ছয়জন গবেষক; তাঁদের হাতে-লেখা ও ছাপা নোট, উৎস-চিত্র, চ্যান মঠের মানচিত্র মিলিয়ে ১৫টি খাতা। ২০১৭ সালের গ্রীষ্মে এই নোটগুলো কেনা হয় এবং এখন কেন্দ্রের গ্রন্থাগারে সংরক্ষিত। প্রাথমিক পরীক্ষাতেই বোঝা গেছে, এগুলো 《臨済録》 পড়ার প্রচলিত ধারণাকে বদলে দিতে পারে — এবং একটি ‘কীভাবে অনুবাদ হয়’ পাঠ্যবস্তু হিসেবে অনুবাদ-শিক্ষণের দুর্লভ উপকরণ।",
    descEn="Fifteen binders of multilingual hand-written and printed notes, source diagrams and Chan monastery maps produced by Ruth Fuller Sasaki, Philip Yampolsky, Burton Watson, Gary Snyder, Iriya Yoshitaka and Yanagida Seizan in a 1950s translation project; acquired in 2017.",
    sourceUrl=CBS,
    accession="Rare Buddhist Texts Archive, Center for Buddhist Studies (15 binders)",
    language="ইংরেজি · চীনা · জাপানি",
    rights=CBS_RIGHTS,
    verification="primary",
    keywords=["Rinzai Roku", "臨済録", "অনুবাদ-নোট", "Gary Snyder", "চ্যান"],
)
