    descBn="১৫টি খাতার প্রথমটি সম্পূর্ণ ডিজিটাইজ করে PDF হিসেবে প্রকাশ করা হয়েছে — ২০২৩ সালের এপ্রিলে আপলোড করা ফাইল, গবেষকরা সরাসরি নামিয়ে নিতে পারেন। নোটের ভেতরে চীনা অক্ষর, জাপানি কানা, ইংরেজি টীকা, তীর-চিহ্ন ও উৎস-সারণি মিশে আছে; অর্থাৎ এটি ‘পরিষ্কার’ প্রকাশিত অনুবাদ নয়, বরং অনুবাদের কর্মশালা — যা পাঠ-ইতিহাসের জন্য বেশি মূল্যবান।",
    descEn="The complete digitisation of the first binder, released as a downloadable PDF in April 2023, showing the messy workshop of a canonical translation in progress.",
