# ৫) উন্মুক্ত সংগ্রহ — উইকিমিডিয়া কমন্স ও জাদুঘর-সংগ্রহ (CC0 / পাবলিক ডোমেইন / CC BY / CC BY-SA)
#
# এখানকার সব ছবিই খোলা লাইসেন্সে প্রকাশিত; তাই পূর্ণ-অনুমতি ছাড়াই স্থানীয় কপি
# রাখা যায় — শর্ত কেবল আলোকচিত্রী, লাইসেন্স ও উৎস-লিংকের স্বীকৃতি (CC BY / BY-SA)।
# থাম্বনেইল `assets/archive/commons/`-এ ৬৪০ px JPEG হিসেবে সংরক্ষিত।
# --------------------------------------------------------------------------- #
COMMONS_LICENCE = {
    "CC BY-SA 4.0": ("খোলা", "https://creativecommons.org/licenses/by-sa/4.0/deed.bn"),
    "CC BY-SA 3.0": ("খোলা", "https://creativecommons.org/licenses/by-sa/3.0/deed.bn"),
    "CC BY-SA 2.0": ("খোলা", "https://creativecommons.org/licenses/by-sa/2.0/deed.bn"),
    "CC BY 4.0": ("খোলা", "https://creativecommons.org/licenses/by/4.0/deed.bn"),
    "CC BY 3.0": ("খোলা", "https://creativecommons.org/licenses/by/3.0/deed.bn"),
    "CC BY 2.0": ("খোলা", "https://creativecommons.org/licenses/by/2.0/deed.bn"),
    "CC0": ("কপিরাইট-ত্যাগ", "https://creativecommons.org/publicdomain/zero/1.0/deed.bn"),
    "Public domain": ("পাবলিক ডোমেইন", "https://commons.wikimedia.org/wiki/Commons:Licensing"),
}


def commons_credit(artist: str, licence: str) -> str:
    """স্বীকৃতি-লাইন: আলোকচিত্রী + লাইসেন্স + কী শর্তে ব্যবহার করা যায়।"""
    if licence in ("Public domain", "CC0"):
        tail = f"{licence} — কপিরাইটের মেয়াদ শেষ বা স্বেচ্ছায় ত্যাগ; ছবিটি আর সব অধিকার-সীমা ছাড়াই ব্যবহারযোগ্য, তবু সৌজন্যে উৎস লেখা রাখা ভালো।"
    else:
        tail = (
            f"{licence} — পুনঃব্যবহারে আলোকচিত্রীর নাম, লাইসেন্সের নাম ও উৎস-লিংক দিতে হবে; "
            "রূপান্তর করলে সেই রূপান্তরও একই লাইসেন্সে ছাড়তে হবে। সব অধিকার মূল আলোকচিত্রীর।"
        )
    return f"আলোকচিত্র: {artist} · Wikimedia Commons — {tail}"


