MET_LICENCE_LABEL = "CC0 (Met Open Access)"
MET_LICENCE_URL = "https://www.metmuseum.org/about-the-met/policies-and-documents/open-access"


def met_credit(object_id: int, credit_line: str) -> str:
    return (
        f"আলোকচিত্র: The Metropolitan Museum of Art, নিউ ইয়র্ক (objectID {object_id}) — "
        f"Met Open Access, CC0: কোনো অধিকার-সীমা নেই, তবু স্বীকৃতি রাখা সৌজন্য। "
        f"জাদুঘরের সংগ্রহ-সূত্র: {credit_line or 'উল্লেখ নেই'}।"
    )


