         descBn="একই পাঠ্যের অপর একটি পাণ্ডুলিপির ছড়ানো পাতা — পাঠ্য অক্ষরের মাঝে ডানে-বাঁয়ে বুদ্ধ ও বোধিসত্ত্বের ক্ষুদ্র চিত্র। পাল পাণ্ডুলিপিতে চিত্রফলকের সংখ্যা ও সাজ-বিন্যাস পাঠ্য-আকার অনুসারে বদলায়; একই গ্রন্থের একাধিক কপি পাশাপাশি দেখলে শিল্পীর নিজস্ব হাত চেনা যায় — তুলনামূলক কলা-ইতিহাসের সহজ উপকরণ।",
         descEn="Dispersed leaves from another copy of the same sutra, showing how Pala illuminators varied their miniatures — useful for comparing individual hands across copies.",
