         descBn="পাণ্ডুলিপির পাতায় আঁকা দৃশ্য: স্তূপ-আকৃতির মন্দিরের ভেতরে সিংহাসনে বুদ্ধ, দুই পাশে বোধিসত্ত্ব। পাল-যুগীয় চিত্রকরের সবচেয়ে বড় অবদান — স্থাপত্যকে চিত্রের ভেতরে ছোট মডেলে রূপ দেওয়া, যাতে আজ বাংলার হারানো মন্দিরগুলোর চেহারা অনুমান করা যায়। ময়নামতি ও সোমপুরের ভাঙা ইট থেকে যা হারিয়েছে, এই পাতাগুলো তাকেই ধরে রেখেছে।",
         descEn="A Buddha enthroned inside a shrine, painted on a palm leaf around 1090 — Pala painters' miniature architecture preserves the look of temples now lost.",
         alt="প্রজ্ঞাপারমিতা পাতায় মন্দিরে সিংহাসনে বুদ্ধ",
