         descBn="পদ্ম হাতে অবলোকিতেশ্বরের রূপ পদ্মপাণি — করুণার বোধিসত্ত্ব। পাল পাণ্ডুলিপিতে পদ্মপাণিকে প্রায়ই পাঠ্যের মাঝে একা আঁকা হতো; বাংলার মঠ থেকে যাওয়া এই মূর্তি-ভাবনা নেপালের ও তিব্বতের ‘চেনরেজিগ’-এর অনুপ্রেরণা।",
         descEn="Padmapani, the lotus-bearing form of Avalokiteshvara, painted between lines of text — an iconography later central to Tibetan Chenrezig practice.",
