         descBn="বসা অবস্থায় পদ্মপাণি; চোখ ও অলংকারে রুপা-তামার নকশা বসানো — পাল ব্রোঞ্জ-শিল্পের সবচেয়ে সূক্ষ্ম কৌশল। রুপার চোখের এই রীতিটি চীনের হয়ে জাপানে গিয়ে ‘গ্যোকুশি’ (সজীব চোখ) নামে পরিচিত হয়; বাংলার ব্রোঞ্জ-মঠগুলোই সেই শিল্পের উৎস-পথের একটি।",
