         descBn="চক্রসম্বর ও বজ্রবারাহীর যুগ্ম মূর্তি — অনুত্বরযোগ-তন্ত্রের কেন্দ্রীয় দেবতা, যাঁর সাধনা বজ্রযানের গোপন রীতির অংশ। বাংলার মঠে অঙ্কিত এই মূর্তির ভারসাম্যপূর্ণ পাথর-খোদাই প্রায় হুবহু নেপাল ও তিব্বতের মণ্ডলে হুবহু অনুসৃত হয়েছিল; প্রকাশ্যে এ ধরনের মূর্তি রাখা ধর্মীয় সাহস ও শিল্প-দক্ষতারই প্রমাণ।",
