         descBn="হাতের তালুর সমান এক বৌদ্ধ দেবমূর্তি — পাল যুগে ব্যক্তিগত পূজা ও ভ্রমণে সঙ্গে রাখার জন্য এমন ছোট মূর্তি গড়া হতো। বাংলাদেশে অনেক গ্রামে এখনো কাদা-পাথর খোদাইয়ের এই ধারা টিকে আছে বলে গবেষকরা মনে করেন; জাদুঘরের এই টুকরোটি সেই দীর্ঘ লোক-ঐতিহ্যের সূচনা দেখায়।",
