         descBn="‘সকল বুদ্ধের ডাকিনী’ — তান্ত্রিক বৌদ্ধ ধারার এক উগ্র-শান্ত মিশ্র দেবী-রূপ, যাঁর নাম সংস্কৃতেই বিরল। বাংলা-বিহারের তান্ত্রিক প্যান্থিয়নে এমন নাম-না-জানা দেবীরা অনেক ছিলেন; এঁদের শনাক্তকরণ আজও গবেষণার বিষয়, কারণ সাধন-সংগ্রহের পাঠ ছাড়া নাম ঠিক করা যায় না।",
