         descBn="পুথির কাঠের প্রচ্ছদে চার বিদ্যাদেবীর ছবি ও তামার রিপুসে-করা সোনার সাজ — প্রজ্ঞা, স্মৃতি, বাক্শক্তি ও একাগ্রতার দেবীরা পুথিকে রক্ষা করতেন বলে বিশ্বাস ছিল। বাংলা-নেপাল দুই অঞ্চলেই পুথির প্রচ্ছদ ছিল সবচেয়ে সাজানো অংশ, কারণ পুথি খোলার আগেই সেটিই দেখা যেত।",
