         descBn="পাল-আকারের পুথির কাঠের দুই প্রচ্ছদ — একটির গায়ে ভারতীয় ছাঁদ, অন্যটিতে তিব্বতি অলংকরণ; এভাবেই বাংলা-বিহারের পুথি তিব্বতে গিয়ে স্থানীয় হাতে নতুন রূপ পেয়েছে। পুথি কপি করার সময় প্রায়ই মূল ভারতীয় প্রচ্ছদ রেখে ভেতরের পাতা নতুন করে লেখা হতো — তিব্বতের গ্রন্থাগারগুলোর সবচেয়ে সাধারণ চিত্র এটি।",
