         descBn="তিব্বতের প্রাচীনতম চিত্রিত পুথি-প্রচ্ছদগুলোর একটি — প্রতি প্রচ্ছদে পাঁচ দেবতা, সোনালি রেখায় আঁকা। ১১ শতকে তিব্বতের রাজারা বাংলার মঠ থেকে ভিক্ষু ও পুথি আনিয়েছিলেন (‘ফির-পুনর্জাগরণ’); সেই সময়ের প্রচ্ছদ-শিল্পে পাল রীতির ছায়া স্পষ্ট।",
