         descBn="হাতের মুঠোর সমান ধাতব স্তূপ — ভক্তেরা প্রার্থনার সময় এগুলো দান করতেন বা বেদিতে রাখতেন। বোধগয়ার মহাবোধি স্তূপের গড়নই এর মূল ছাঁদ; বাংলার পাহাড়পুর ও ময়নামতির ইটের স্তূপগুলোও একই আদলের বড় সংস্করণ — ছোট এই মডেল থেকেই হারানো স্থাপত্যের অনুপাত বোঝা যায়।",
