         descBn="পশ্চিম তিব্বতের পুথিতে প্রজ্ঞাপারমিতার চিত্র — এখানে লেখা হয়েছিল কাগজে, তালপাতায় নয়, কারণ হিমালয়ের আবহাওয়ায় তালপাতা টিকত না। কিন্তু ছবির রীতিটি বাংলারই: একই মুদ্রা, একই আসন, একই পোশাক-ভাঁজ — পাল শিল্পের ‘দূরবর্তী সন্তান’।",
