def interleave(rows: list[dict]) -> list[dict]:
    """প্রথম পাতা যেন এক-সংগ্রহে আটকে না থাকে — চার প্রতিষ্ঠানের রেকর্ড পালাক্রমে সাজানো।

    (ফিল্টার বা খোঁজে ক্রম বদলায় না; কেবল ডিফল্ট তালিকার শুরুর ছন্দ।)"""
    order = ["open", "bdrc", "bop", "kabc", "cbs"]
    # ছবি-যুক্ত রেকর্ড আগে — যেন প্রথম পাতাতেই আসল আলোকচিত্র দেখা যায়
    buckets = {
        key: sorted([r for r in rows if r["collection"] == key], key=lambda r: 0 if r.get("imageUrl") else 1)
        for key in order
    }
    merged: list[dict] = []
    while any(buckets.values()):
        for key in order:
            if buckets[key]:
                merged.append(buckets[key].pop(0))
    return merged


ITEMS = interleave(ITEMS)

# --------------------------------------------------------------------------- #
# ছবি না থাকলে রেকর্ড রাখা হয় না (ব্যবহারকারীর নির্দেশ, ২০২৬-১১-০১)।
# সামনে যেসব রেকর্ডে ছবি যোগ করা সম্ভব হয়নি, সেগুলো এখানে বাদ পড়ে — নামগুলো
# `removed_notes`-এ রাখা হয় যাতে পরে ছবি পাওয়া গেলে ফিরিয়ে আনা যায়।
# --------------------------------------------------------------------------- #
# --------------------------------------------------------------------------- #
# ছবির আনুপাতিক মাপ (প্রস্থ ÷ উচ্চতা) — অতি-সরু পাতা/স্ক্রল আলাদা করে দেখানোর জন্য।
# 5-এর বেশি হলে CSS ‘pa-strip’ শ্রেণি দিয়ে পাতার ম্যাট-রঙ দেখায়।
# --------------------------------------------------------------------------- #
def _ratio(rec: dict) -> None:
    path = ROOT / (rec.get("imageUrl") or "")
    try:
        from PIL import Image
        with Image.open(path) as im:
            rec["aspect"] = round(im.width / max(im.height, 1), 2)
    except Exception:
        rec["aspect"] = 0


for _r in ITEMS:
    _ratio(_r)

