def assign_region(rec: dict) -> str:
    if rec.get("region"):
        return rec["region"]
    blob = " ".join(str(rec.get(k) or "") for k in ("placeBn", "titleBn", "titleEn", "origTitle", "descEn"))
    if rec.get("collection") == "kabc":
        return "eastasia"
    if rec.get("collection") == "bdrc":
        return "himalaya"
    if rec.get("collection") == "bop":
        return "seasia"
    for key, words in _REGION_RULES:
        if any(w in blob for w in words):
            return key
    return "bangladesh"


for _r in ITEMS:
    _r["region"] = assign_region(_r)

