def normalise_image(path: Path) -> None:
    """PNG/WebP হলে ছোট JPEG-এ নামায় (কার্ডের জন্য যথেষ্ট, ফাইল হালকা থাকে)।"""
    if path.suffix.lower() not in {".jpg", ".jpeg"}:
        return
    try:
        from PIL import Image
    except ImportError:
        return
    if path.read_bytes()[:4] == b"\x89PNG" or path.read_bytes()[:4] == b"RIFF":
        with Image.open(path) as im:
            im = im.convert("RGB")
            im.thumbnail((1000, 1000))
            im.save(path, "JPEG", quality=84, optimize=True)


def fetch_thumbs() -> int:
    """JSON-এ উল্লেখিত রিমোট থাম্বনেইলগুলো assets/archive/partners/ এ নামায়।"""
    out_dir = ROOT / THUMB_DIR
    out_dir.mkdir(parents=True, exist_ok=True)
    ctx = ssl.create_default_context()
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE  # kabc.dongguk.edu-র চেইন কিছু ক্লায়েন্টে অসম্পূর্ণ
    done = 0
    for item in ITEMS:
        remote = item.get("imageSourceUrl") or ""
        if not remote:
            continue
        dest = ROOT / item["imageUrl"]
        if dest.exists():
            normalise_image(dest)
            continue
        try:
            req = urllib.request.Request(remote, headers={"User-Agent": "Mozilla/5.0 (compatible; CharyabhumiArchive/1.0)"})
            with urllib.request.urlopen(req, timeout=45, context=ctx) as resp:
                dest.write_bytes(resp.read())
            done += 1
        except Exception:
            # TLS চেইন সমস্যা হলে curl -k দিয়ে আবার চেষ্টা
            subprocess.run(["curl", "-sk", "--max-time", "45", "-o", str(dest), remote], check=False)
            if dest.exists() and dest.stat().st_size:
                done += 1
            else:
                print(f"  ! {item['id']} -> {remote}")
                continue
        normalise_image(dest)
    if done:
        print(f"downloaded {done} thumbnails into {THUMB_DIR}/")
    return 0


def main() -> int:
    valid_mt = {m["key"] for m in MEDIA_TYPES}
    valid_period = {p["key"] for p in PERIODS}
    valid_coll = {c["key"] for c in COLLECTIONS}
    valid_rights = set(RIGHTS)
    seen = set()
    for item in ITEMS:
        assert item["id"] not in seen, f"duplicate id {item['id']}"
        seen.add(item["id"])
        assert item["collection"] in valid_coll, item["id"]
        assert item["mediaType"] in valid_mt, item["id"]
        assert item["period"] in valid_period, item["id"]
        assert item["rights"] in valid_rights, item["id"]
        for field in ("titleBn", "titleEn", "descBn", "sourceUrl", "dateBn"):
            assert item.get(field), f"{item['id']} missing {field}"
        if item.get("imageUrl"):
            assert item.get("imageAltBn"), f"{item['id']} image needs alt text"
    OUT.write_text(json.dumps(PAYLOAD, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
    if "--fetch" in sys.argv:
        fetch_thumbs()
    per = {}
    for item in ITEMS:
        per[item["collection"]] = per.get(item["collection"], 0) + 1
    print(f"wrote {OUT.relative_to(ROOT)} — {len(ITEMS)} items")
    for key in ("bdrc", "bop", "kabc", "cbs"):
        print(f"  {key:6} {per.get(key, 0)}")
    # মালিকের সম্পাদনা ও অনুমোদিত সম্প্রদায়-জমা (data/edits.json, data/contributions.json)
    # থাকলে সেগুলো মিশিয়ে দেওয়া হয় — নইলে স্ক্রিপ্ট চুপচাপ এগিয়ে যায়।
    try:
        import subprocess
        merge = Path(__file__).resolve().parent / "merge_contributions.py"
        if merge.exists():
            subprocess.run([sys.executable, str(merge)], check=False)
    except Exception as exc:  # noqa: BLE001
        print("  merge skipped:", exc)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
